import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.BFMro0Mr.js";const u=JSON.parse('{"title":"Reference","description":"Every public class and interface of Nette API 3.x by namespace, with a one line description and a link to the guide page.","frontmatter":{"title":"Reference","description":"Every public class and interface of Nette API 3.x by namespace, with a one line description and a link to the guide page."},"headers":[],"relativePath":"api/reference.md","filePath":"api/reference.md","lastUpdated":1793389501000}'),a={name:"api/reference.md"};function i(n,e,c,s,p,h){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h1><p>All classes live under <code>Tomaj\\NetteApi</code>.</p><h2 id="core" tabindex="-1">Core <a class="header-anchor" href="#core" aria-label="Permalink to &quot;Core&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>What it does</th><th>Guide</th></tr></thead><tbody><tr><td><code>ApiDecider</code></td><td>registry of endpoints: <code>addApi()</code>, <code>getApi()</code>, <code>getApis()</code>, <code>enableGlobalPreflight()</code></td><td><a href="/nette-api/pr-preview/pr-238/guide/architecture.html">Architecture</a></td></tr><tr><td><code>Api</code></td><td>one registered endpoint: endpoint, handler, authorization, rate limit</td><td><a href="/nette-api/pr-preview/pr-238/guide/architecture.html">Architecture</a></td></tr><tr><td><code>ApiHolder</code></td><td>used inside <code>ApiDecider</code>: how it stores an endpoint before its handler is created; the handler can still be a class or service name</td><td><a href="/nette-api/pr-preview/pr-238/guide/api-decider.html#three-ways-to-pass-a-handler">ApiDecider</a></td></tr><tr><td><code>EndpointIdentifier</code> / <code>EndpointInterface</code></td><td>method, version, package, action</td><td><a href="/nette-api/pr-preview/pr-238/guide/handlers.html#registering-a-handler">Handlers</a></td></tr><tr><td><code>Presenters\\ApiPresenter</code></td><td>runs a request step by step</td><td><a href="/nette-api/pr-preview/pr-238/guide/presenter.html">ApiPresenter pipeline</a></td></tr><tr><td><code>DI\\NetteApiExtension</code></td><td>registers the services and endpoints from the <code>api:</code> neon section (4.0.0)</td><td><a href="/nette-api/pr-preview/pr-238/guide/di-extension.html">DI extension</a></td></tr><tr><td><code>Attribute\\Get</code>, <code>Post</code>, <code>Put</code>, <code>Patch</code>, <code>Delete</code>, <code>Endpoint</code></td><td>endpoint attributes on a handler class (4.0.0)</td><td><a href="/nette-api/pr-preview/pr-238/guide/attributes.html">Attribute endpoints</a></td></tr><tr><td><code>Attribute\\Authorization</code>, <code>Attribute\\RateLimit</code></td><td>authorization and rate limit of the attribute endpoints of a class (4.0.0)</td><td><a href="/nette-api/pr-preview/pr-238/guide/attributes.html#authorization-and-rate-limit">Attribute endpoints</a></td></tr><tr><td><code>DI\\EndpointDefinition</code></td><td>one endpoint for <code>NetteApiExtension::addEndpoint()</code> from another extension (4.0.0)</td><td><a href="/nette-api/pr-preview/pr-238/guide/di-extension.html#can-another-extension-add-endpoints">DI extension</a></td></tr></tbody></table><h2 id="handlers" tabindex="-1">Handlers <a class="header-anchor" href="#handlers" aria-label="Permalink to &quot;Handlers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>What it does</th><th>Guide</th></tr></thead><tbody><tr><td><code>Handlers\\ApiHandlerInterface</code>, <code>BaseHandler</code></td><td>your endpoints</td><td><a href="/nette-api/pr-preview/pr-238/guide/handlers.html">Handlers</a></td></tr><tr><td><code>Handlers\\OpenApiHandler</code></td><td>OpenAPI 3.0 document</td><td><a href="/nette-api/pr-preview/pr-238/guide/openapi.html">OpenAPI</a></td></tr><tr><td><code>Handlers\\ApiListingHandler</code></td><td>JSON list of the endpoints in its own version</td><td><a href="/nette-api/pr-preview/pr-238/guide/handlers.html#handlers-that-ship-with-the-library">Handlers</a></td></tr><tr><td><code>Handlers\\AlwaysOkHandler</code>, <code>EchoHandler</code></td><td>health check and test endpoints</td><td><a href="/nette-api/pr-preview/pr-238/guide/handlers.html#handlers-that-ship-with-the-library">Handlers</a></td></tr><tr><td><code>Handlers\\DefaultHandler</code></td><td><code>404 Unknown api endpoint</code></td><td><a href="/nette-api/pr-preview/pr-238/guide/architecture.html">Architecture</a></td></tr><tr><td><code>Handlers\\CorsPreflightHandler(Interface)</code></td><td>answers <code>OPTIONS</code></td><td><a href="/nette-api/pr-preview/pr-238/guide/cors.html#preflight-requests">CORS</a></td></tr></tbody></table><h2 id="params-and-validation" tabindex="-1">Params and validation <a class="header-anchor" href="#params-and-validation" aria-label="Permalink to &quot;Params and validation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>What it does</th><th>Guide</th></tr></thead><tbody><tr><td><code>Params\\GetInputParam</code>, <code>PostInputParam</code>, <code>PutInputParam</code>, <code>CookieInputParam</code>, <code>FileInputParam</code>, <code>RawInputParam</code>, <code>JsonInputParam</code></td><td>one input each</td><td><a href="/nette-api/pr-preview/pr-238/guide/params.html">Params</a></td></tr><tr><td><code>Params\\InputParam</code>, <code>ParamInterface</code>, <code>ParamsProcessor</code></td><td>the base class and the processing</td><td><a href="/nette-api/pr-preview/pr-238/guide/params.html">Params</a></td></tr><tr><td><code>Validation\\InputValidator</code>, <code>JsonSchemaValidator</code>, <code>InputType</code> (enum)</td><td>value checks</td><td><a href="/nette-api/pr-preview/pr-238/guide/params.html#types">Params</a></td></tr><tr><td><code>ValidationResult\\ValidationResult(Interface)</code></td><td>the result of a check</td><td><a href="/nette-api/pr-preview/pr-238/guide/params.html">Params</a></td></tr></tbody></table><h2 id="responses-and-outputs" tabindex="-1">Responses and outputs <a class="header-anchor" href="#responses-and-outputs" aria-label="Permalink to &quot;Responses and outputs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>What it does</th><th>Guide</th></tr></thead><tbody><tr><td><code>Response\\ResponseInterface</code></td><td>what every response implements</td><td><a href="/nette-api/pr-preview/pr-238/guide/outputs.html#responses">Outputs</a></td></tr><tr><td><code>Response\\JsonApiResponse</code>, <code>TextApiResponse</code>, <code>XmlApiResponse</code>, <code>RedirectResponse</code></td><td>what <code>handle()</code> returns</td><td><a href="/nette-api/pr-preview/pr-238/guide/outputs.html#responses">Outputs</a></td></tr><tr><td><code>Output\\JsonOutput</code>, <code>RedirectOutput</code>, <code>AbstractOutput</code>, <code>OutputInterface</code></td><td>declared outputs</td><td><a href="/nette-api/pr-preview/pr-238/guide/outputs.html#outputs">Outputs</a></td></tr><tr><td><code>Output\\Configurator\\ConfiguratorInterface</code>, <code>EnvConfigurator</code>, <code>QueryConfigurator</code>, <code>DebuggerConfigurator</code></td><td>when to check outputs and show details</td><td><a href="/nette-api/pr-preview/pr-238/guide/outputs.html#when-outputs-are-validated">Outputs</a></td></tr><tr><td><code>Error\\ErrorHandlerInterface</code>, <code>DefaultErrorHandler</code></td><td>error responses</td><td><a href="/nette-api/pr-preview/pr-238/guide/errors.html">Error handling</a></td></tr><tr><td><code>Error\\ProblemDetailsErrorHandler</code>, <code>NegotiatingErrorHandler</code>, <code>ProblemDetails</code>, <code>Response\\ProblemDetailsResponse</code></td><td>RFC 9457 errors, 4.0.0</td><td><a href="/nette-api/pr-preview/pr-238/guide/problem-details.html">Problem Details</a></td></tr></tbody></table><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>What it does</th><th>Guide</th></tr></thead><tbody><tr><td><code>Authorization\\NoAuthorization</code>, <code>BearerTokenAuthorization</code>, <code>HeaderApiKeyAuthentication</code>, <code>QueryApiKeyAuthentication</code>, <code>CookieApiKeyAuthentication</code>, <code>BasicAuthentication</code></td><td>built-in authorization</td><td><a href="/nette-api/pr-preview/pr-238/guide/authorization.html">Authorization</a></td></tr><tr><td><code>Authorization\\ApiAuthorizationInterface</code>, <code>TokenAuthorization</code></td><td>your own</td><td><a href="/nette-api/pr-preview/pr-238/guide/authorization.html#your-own-authorization">Authorization</a></td></tr><tr><td><code>Misc\\TokenRepositoryInterface</code>, <code>StaticTokenRepository</code></td><td>tokens and their IPs</td><td><a href="/nette-api/pr-preview/pr-238/guide/authorization.html#tokens-and-ip-restrictions">Authorization</a></td></tr><tr><td><code>Misc\\IpDetectorInterface</code>, <code>IpDetector</code>, <code>StaticIpDetector</code></td><td>the client IP</td><td><a href="/nette-api/pr-preview/pr-238/guide/authorization.html#tokens-and-ip-restrictions">Authorization</a></td></tr><tr><td><code>RateLimit\\RateLimiterInterface</code>, <code>RateLimitResult</code>, <code>FixedWindowLimiter</code>, <code>SlidingWindowLimiter</code>, <code>TokenBucketLimiter</code>, <code>RateLimiterChain</code>, <code>NoRateLimit</code></td><td>rate limiting (4.0.0)</td><td></td></tr><tr><td><code>RateLimit\\Algorithm\\RateLimitAlgorithmInterface</code>, <code>Storage\\RateLimitStorageInterface</code>, <code>Key\\RateLimitKeyInterface</code>, <code>Redis\\RedisClientInterface</code></td><td>own algorithms, storages, keys and Redis clients (4.0.0)</td><td></td></tr><tr><td><code>RateLimit\\RateLimitInterface</code>, <code>RateLimitResponse</code></td><td>the 3.x rate limit, deprecated, removed in 5.0</td><td><a href="/nette-api/pr-preview/pr-238/guide/rate-limit.html">Rate limiting</a></td></tr></tbody></table><h2 id="logging-links-and-console" tabindex="-1">Logging, links and console <a class="header-anchor" href="#logging-links-and-console" aria-label="Permalink to &quot;Logging, links and console&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>What it does</th><th>Guide</th></tr></thead><tbody><tr><td><code>Logger\\ApiLoggerInterface</code></td><td>request log</td><td><a href="/nette-api/pr-preview/pr-238/guide/logging.html">Logging</a></td></tr><tr><td><code>Link\\ApiLink</code>, <code>ApiLinkExtension</code>, <code>ApiLinkNode</code></td><td>URLs and the <code>{apiLink}</code> tag</td><td><a href="/nette-api/pr-preview/pr-238/guide/links.html">Links</a></td></tr><tr><td><code>Component\\ApiListingControl</code>, <code>ApiConsoleControl</code>, <code>ApiConsoleFormFactoryInterface</code>, <code>DefaultApiConsoleFormFactory</code></td><td>web console</td><td><a href="/nette-api/pr-preview/pr-238/guide/console.html">Web console</a></td></tr><tr><td><code>Misc\\ConsoleRequest</code>, <code>ConsoleResponse</code></td><td>the console&#39;s cURL request</td><td><a href="/nette-api/pr-preview/pr-238/guide/console.html">Web console</a></td></tr><tr><td><code>Misc\\CorsOriginAllowlist</code></td><td>internal (<code>@internal</code>), used by <code>setCorsAllowedOrigins()</code>; may change in 4.0</td><td><a href="/nette-api/pr-preview/pr-238/guide/cors.html#allowed-origins">CORS</a></td></tr><tr><td><code>Misc\\OpenApiTransform</code></td><td>helpers for OpenAPI</td><td><a href="/nette-api/pr-preview/pr-238/guide/openapi.html">OpenAPI</a></td></tr></tbody></table><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><h3 id="which-classes-are-final" tabindex="-1">Which classes are final? <a class="header-anchor" href="#which-classes-are-final" aria-label="Permalink to &quot;Which classes are final?&quot;">​</a></h3><p><code>Presenters\\ApiPresenter</code>, <code>Error\\DefaultErrorHandler</code>, the Latte classes <code>Link\\ApiLinkExtension</code> and <code>Link\\ApiLinkNode</code>, and the internal <code>Misc\\CorsOriginAllowlist</code> are <code>final</code>; wrap them instead of extending. See <a href="/nette-api/pr-preview/pr-238/guide/errors.html#your-own-error-handler">Error handling</a>.</p><p>Since 4.0 these are <code>final</code> too: <code>Api</code>, <code>ApiHolder</code>, <code>EndpointIdentifier</code>, <code>Authorization\\NoAuthorization</code>, <code>RateLimit\\NoRateLimit</code>, <code>RateLimit\\RateLimitResponse</code>, <code>Misc\\IpDetector</code>, <code>Misc\\StaticIpDetector</code>, <code>Misc\\StaticTokenRepository</code>, <code>Misc\\ConsoleRequest</code>, <code>Misc\\ConsoleResponse</code>, <code>Misc\\OpenApiTransform</code>, <code>Params\\ParamsProcessor</code>, <code>Validation\\InputValidator</code>, <code>Validation\\JsonSchemaValidator</code>, <code>ValidationResult\\ValidationResult</code>, the output configurators <code>DebuggerConfigurator</code>, <code>EnvConfigurator</code> and <code>QueryConfigurator</code>, and <code>OpenApi\\SchemaRegistry</code> and <code>OpenApi\\EndpointFilter</code>. Implement the matching interface (<code>IpDetectorInterface</code>, <code>TokenRepositoryInterface</code>, <code>ApiAuthorizationInterface</code>, <code>RateLimitInterface</code>, <code>ConfiguratorInterface</code>, …) instead of extending them. Handlers, params, outputs, responses, authorizations, the OpenAPI builders, <code>ApiDecider</code>, <code>ApiLink</code>, the console components and <code>DefaultApiConsoleFormFactory</code> stay open for extension. The exception is <code>Handlers\\DefaultHandler</code>, which is <code>final</code>; customize the <code>404</code> in the error handler&#39;s <code>handleNotFound()</code>.</p><h3 id="where-are-the-method-signatures" tabindex="-1">Where are the method signatures? <a class="header-anchor" href="#where-are-the-method-signatures" aria-label="Permalink to &quot;Where are the method signatures?&quot;">​</a></h3><p>In the source on <a href="https://github.com/tomaj/nette-api/tree/master/src" target="_blank" rel="noreferrer">GitHub</a>; the guide pages show the ones you use.</p><h3 id="which-classes-are-deprecated" tabindex="-1">Which classes are deprecated? <a class="header-anchor" href="#which-classes-are-deprecated" aria-label="Permalink to &quot;Which classes are deprecated?&quot;">​</a></h3><p>None. <code>setExample()</code> on params and outputs was removed in 4.0; use <code>addExample()</code>. The old <code>StaticBearerTokenRepository</code> and <code>BearerTokenRepositoryInterface</code> were removed in 4.0. Use <code>StaticTokenRepository</code> and <code>TokenRepositoryInterface</code>, which work the same way.</p><h3 id="is-there-a-di-extension" tabindex="-1">Is there a DI extension? <a class="header-anchor" href="#is-there-a-di-extension" aria-label="Permalink to &quot;Is there a DI extension?&quot;">​</a></h3><p>Yes, since 4.0.0: <code>DI\\NetteApiExtension</code> configures the whole API from one <code>api:</code> neon section, see <a href="/nette-api/pr-preview/pr-238/guide/di-extension.html">DI extension</a>. Registering plain services in NEON, as in <a href="/nette-api/pr-preview/pr-238/guide/getting-started.html">Getting started</a>, keeps working.</p><h3 id="what-does-a-full-project-look-like" tabindex="-1">What does a full project look like? <a class="header-anchor" href="#what-does-a-full-project-look-like" aria-label="Permalink to &quot;What does a full project look like?&quot;">​</a></h3><p>See the <a href="/nette-api/pr-preview/pr-238/examples/">examples</a>.</p>',26)])])}const m=t(a,[["render",i]]);export{u as __pageData,m as default};
